# Define a class for the mathematical function to be integrated
class GSLFunction:
    def __init__(self, func):
        self.func = func

    # Wrap the Python callable in a C-compatible object
    @staticmethod
    def wrap(func):
        return CFUNCTYPE(c_double, c_double)(func)

# Define a class for the workspace of the integration routine
class CQuadWorkspace:
    def __init__(self, size):
        self.size = size

    # Wrap the workspace in a C-compatible object
    @staticmethod
    def wrap(workspace):
        return POINTER(c_double)()

# Define the integration function that takes the mathematical function, start and end of the interval, absolute and relative error tolerances, and the size of the workspace as input
def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    # Create a C-compatible object for the mathematical function
    gsl_function = GSLFunction.wrap(func)

    # Create a C-compatible object for the workspace
    workspace = CQuadWorkspace.wrap(workspace_size)

    # Perform the integration using the GNU Scientific Library's C function 'gsl_integration_cquad'
    result = gsl.gsl_integration_cquad(gsl_function, c_double(a), c_double(b), c_double(epsabs), c_double(epsrel), workspace)

    # Extract the computed integral and estimated absolute error from the C-compatible object
    integral = result.contents.integral
    err = result.contents.err

    # Free the memory used by the workspace
    gslcblas.gsl_vector_free(workspace)

    # Return the computed integral, estimated absolute error, and number of function evaluations
    return (integral, err, result.contents.neval)

