import ctypes

def prime_factors(num):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    fft_factorize = gsl.gsl_factorize
    factors = []
    while num > 1:
        factor, remainder = fft_factorize(num)
        if factor == 0:
            break
        factors.append(factor)
        num = remainder
    return factors

