This code defines a `GSLFunction` class that wraps a Python callable and exposes it to C functions via the `__call__()` method. The `wrapper()` function is used to pass the Python callable to the GSL library's `gsl_integration_qags()` function, which computes the definite integral of the wrapped function between limits `a` and `b`, with a singularity at `c`. The resulting JSON object contains the computed integral value and the estimated absolute error.

import ctypes
import numpy as np

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def function(self, x, params):
        return self.func(x)

def wrapper(x, params):
    return params[0].function(x, params)

def test_func(x):
    return np.sin(x) + 3*x**2

def integrate_with_singularity(func, a, b, c):
    # Load the GSL library
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Create a function pointer for the wrapper function
    func_ptr = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)

    # Wrap the Python function in a GSL function
    gsl_func = GSLFunction(wrapper)

    # Create a tuple of parameters for the wrapper function
    params = (gsl_func, (a, b, c))

    # Call the GSL qc25c function with the wrapped function and parameters
    result = gsl.qc25c(func_ptr(wrapper), params, a, b)

    # Return the result as a tuple of values
    return (result[0], result[1], result[2])

