class gsl_function(ctypes.Structure):
    _fields_ = [("function", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.POINTER(ctypes.c_double))),
                ("params", ctypes.POINTER(ctypes.c_void_p))]

class gsl_integration_qaws_table(ctypes.Structure):
    _fields_ = [("table", ctypes.POINTER(gsl_function)),
                ("n", ctypes.c_size_t),
                ("a", ctypes.c_double),
                ("b", ctypes.c_double)]

class gsl_integration_workspace(ctypes.Structure):
    _fields_ = [("workspace", ctypes.POINTER(gsl_function)),
                ("size", ctypes.c_size_t),
                ("owner", ctypes.c_int)]

def create_workspace(limit):
    return gsl.gsl_integration_workspace_alloc(ctypes.c_size_t(limit))

def create_qaws_table():
    return gsl.gsl_integration_qaws_table_alloc(0, 1e-4, 1e-6)

def free_workspace(workspace):
    gsl.gsl_integration_workspace_free(workspace)

def free_qaws_table(table):
    gsl.gsl_integration_qaws_table_free(table)

def my_function(x):
    return x * x + 1

def gsl_integration_qaws(f, a, b, table, epsabs, epsrel, limit, workspace):
    return gsl.gsl_integration_qaws(f, ctypes.c_double(a), ctypes.c_double(b), table, ctypes.c_double(epsabs), ctypes.c_double(epsrel), ctypes.c_size_t(limit), workspace)

def main():
    # Create a function object for the integrand
    f = gsl_function()
    f.function = my_function
    f.params = None

    # Create a QAW's table object
    table = create_qaws_table()

    # Create a workspace object
    workspace = create_workspace(1000)

    # Perform the integration
    result, error = gsl_integration_qaws(f, 0, 1, table, 1e-4, 1e-6, 1000, workspace)

    # Free the QAW's table and workspace objects
    free_qaws_table(table)
    free_workspace(workspace)

    # Return the result and error as a JSON object
    return {"result": result, "error": error}

if __name__ == "__main__":
    main()

