class GslRng:
    def __init__(self):
        self.state = None
        self.type = None

    def init(self, rng_type, seed):
        self.state = rng_type.alloc()
        self.type = rng_type
        self.set(seed)

    def set(self, seed):
        self.type.set(self.state, seed)

    def get_double(self):
        return self.type.get_double(self.state)

