    def __init__(self, type):
        self.type = type

    def alloc(self):
        return ctypes.cast(libgsl.gsl_rng_alloc(), ctypes.POINTER(GslRng)).contents

    def set(self, state, seed):
        libgsl.gsl_rng_set(state, seed)

    def get_double(self, state):
        return libgsl.gsl_rng_get(state)

