import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix

    @staticmethod
    def matrix_to_gsl(matrix):
        nrows = len(matrix)
        ncols = len(matrix[0]) if nrows > 0 else 0
        gsl_matrix = GSLMatrix(matrix)
        return gsl_matrix

    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix):
        numpy_array = np.empty((nrows, ncols), dtype=np.float64)
        for i in range(nrows):
            for j in range(ncols):
                numpy_array[i][j] = gsl_matrix.matrix[i][j]
        return numpy_array

    @staticmethod
    def compute_matrix_exponential(matrix, mode):
        if not GSLMatrix.is_square_matrix(matrix):
            raise ValueError("Input matrix must be square")

        gsl_matrix = GSLMatrix.matrix_to_gsl(matrix)
        gsl_matrix_ptr = POINTER(c_double*nrows*ncols)(*[pointer(x) for x in gsl_matrix])

        try:
            gsl = CDLL("/usr/local/gsl/lib/libgsl.so")
            gsl_linalg_exponential_ss = gsl.gsl_linalg_exponential_ss
            gsl_linalg_exponential_ss.argtypes = [POINTER(c_double), c_int, POINTER(c_double)]
            gsl_linalg_exponential_ss.restype = None
            gsl_linalg_exponential_ss(gsl_matrix_ptr, c_int(mode), pointer(gsl_matrix))
        except:
            raise ValueError("GSL library not found")

        return GSLMatrix.gsl_matrix_to_numpy(gsl_matrix)

    @staticmethod
    def is_square_matrix(matrix):
