        self.data = (ctypes.c_double * self.size)()

def householder_transform(input_vector):
    vect = GSLVector(len(input_vector))
    for i in range(len(input_vector)):
        vect.data[i] = input_vector[i]
    tau = gsl.gsl_linalg_householder_transform(ctypes.byref(vect), 1)
    return (tau, [vect.data[i] for i in range(len(input_vector))])

