def create_and_manipulate_matrix():
    # Load GSL library
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so", mode=ctypes.RTLD_GLOBAL)
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so")

