    class GSLMatrix(ctypes.Structure):
        _fields_ = [("size1", ctypes.c_size_t), ("size2", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double))]

    gsl_matrix_get = gsl.gsl_matrix_get
    gsl_matrix_get.argtypes = [GSLMatrix, ctypes.c_size_t, ctypes.c_size_t]
    gsl_matrix_get.restype = ctypes.c_double

    # Create GSL matrix of size 2x2
    mat = GSLMatrix(2, 2)

    # Set elements of the matrix
    for i in range(2):
        for j in range(2):
            gsl_matrix_set(mat, i, j, i * j)

    # Retrieve elements of the matrix
    result = {}
    for i in range(2):
        for j in range(2):
            result[(i, j)] = gsl_matrix_get(mat, i, j)

